import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { IonRefresher, Platform } from "@ionic/angular";
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { TranslateService } from "@ngx-translate/core";
import { File } from '@awesome-cordova-plugins/file/ngx';
import {jsPDF} from 'jspdf';  
import html2canvas from 'html2canvas';
import { ApiService } from "src/app/services/tnvn/services/api.service";
import { FilePath } from '@awesome-cordova-plugins/file-path/ngx';
import domtoimage from 'dom-to-image';
import { SocialSharing } from '@ionic-native/social-sharing/ngx';
import { FileOpener } from '@awesome-cordova-plugins/file-opener/ngx';
import moment from 'moment';

@Component({
  selector: 'app-inspection-report',
  templateUrl: './inspection-report.page.html',
  styleUrls: ['./inspection-report.page.scss'],
})
export class inspectionReportPage implements OnInit {
  emis_username: any;
  hoddata: any[];
  public teacherDetails: any;
  public discussReport: any;
  Report:any;
  dateSelected = false;
  selectedMonthData:any;
  selectedYearData:any;
  selectedMonthAndYear:any;
  public selectedclass: any;
  subjectData:any;
  public date=new Date().toLocaleDateString() ;
  observedDate: any;
  public studentTested: any;
  public remarks: any;
  innerText:any;
  public identifyAlphabet: any;
  public TodayReport: any;
  public areastrength: any;
  public areaImprovement: any;
  public assessmentResults: any;
  public school_name: any;
  public class_observed: any;
  public inspection_date: any;  
  public teacher_emisid: any;
  public teacher_name: any;
  public final_remarks: any;
  public strength: any=[];
  public improvement: any=[];
  public schoolDetails: any;
  public schoolObserved: any;
  public standardObserved: any;
  public subject: any;
  divdata:any;
  public selectedSection: any;
  languageType: any;
  noData: boolean;  
  doc:any;
  classTarget : any;
  public shareonwhatsapp: any;
  selectedMonth:any;
  setMaxDate:any;
  constructor(private alertService: AlertService, private apiService: ApiService,private userSessionService: UserSessionService, 
    private router: Router,
    private filePath: FilePath,    
    private platform: Platform,
    public _apiService: ApiService,
    private _translate: TranslateService,
    private socialSharing: SocialSharing,
    private file: File,    
    private fileOpener: FileOpener,
    private userService: UserService) { }

  ngOnInit() {
    this.setMaxDate = moment(new Date()).format("yyyy-MM-DD");
  }

  ionViewDidEnter() {
    this.setMaxDate = moment(new Date()).format("yyyy-MM-DD");
    this.appLanguage();
    this.selectedMonth = new Date();
    this.emis_username = this.userSessionService.emis_username();
    this.getHODInspection();
    
  }
  appLanguage() {
    this.languageType = 'en'
    this._apiService.languageInfo.subscribe((data: any) => {
      this.languageType = 'en';      
      this._translate.use(this.languageType);
      this._initialiseTranslation();
    });
  }
  _initialiseTranslation(): void {
    
    this._translate.get("observedDate").subscribe((res: string) => {
      this.observedDate = res;
    });
    this._translate.get("Report").subscribe((res: string) => {
      this.Report = res;
    });
    this._translate.get("discussReport").subscribe((res: string) => {
      this.discussReport = res;
    });
    this._translate.get("schoolObserved").subscribe((res: string) => {
      this.schoolObserved = res;
    });
    this._translate.get("standardObserved").subscribe((res: string) => {
      this.standardObserved = res;
    });
    this._translate.get("subject").subscribe((res: string) => {
      this.subject = res;
    });
    this._translate.get("studentTested").subscribe((res: string) => {
      this.studentTested = res;
    });
    this._translate.get("TodayReport").subscribe((res: string) => {
      this.TodayReport = res;
    });
    this._translate.get("areastrength").subscribe((res: string) => {
      this.areastrength = res;
    });
    this._translate.get("areaImprovement").subscribe((res: string) => {
      this.areaImprovement = res;
    });
    this._translate.get("assessmentResults").subscribe((res: string) => {
      this.assessmentResults = res;
    });
    
  }  
  async downloadInspection(index){
    let data = this.hoddata[index];    
    this.school_name = data.school_name;
    this.class_observed = data.class_observed;    
    this.inspection_date = data.inspection_date;
    this.subjectData = data.subject_name;
    this.teacher_emisid = data.teacher_emisid;
    this.teacher_name = data.teacher_name;
    this.final_remarks = data.final_remarks;
    this.strength = data.strength.split("|").slice(0,5);
    this.improvement = data.improvement.split("|").slice(0,5);    
    let Strengthdata = '';         
    let div = document.getElementById("PrintReport");        
    Strengthdata += "<section><h5><span>"+this.areastrength+"</span>:</h5><ul style='list-style-type:decimal'>"
    for(var i = 0;i<this.strength.length;i++){
      Strengthdata += "<li style='color: #27ae60;font-weight: bold'>"+this.strength[i]+"</li>"
    }
    Strengthdata+="</ul>"
    Strengthdata += "<h5><span>"+this.areaImprovement+"</span>:</h5><ul style='list-style-type:decimal'>"
    for(var j = 0;j<this.improvement.length;j++){
      Strengthdata += "<li style='color: #f2994a;font-weight: bold'>"+this.improvement[j]+"</li>"
    }
    Strengthdata+="</ul></section>"    
    div.innerHTML = "<div style='text-align:center'><p style='font-size:12'><span >"+this.discussReport+"</span><br /><b>"+ this.teacher_name+"["+this.teacher_emisid+"]</b></p></div><div style='font-size:color:#000'><p ><span >"+this.observedDate+"</span>:<b>"+this.inspection_date+"</b></p><p style='margin-bottom:2px'><span>"+this.schoolObserved+"</span>: <b>"+this.school_name+"</b></p><p style='margin-bottom:2px'><span>"+this.standardObserved+"</span>:<b>"+ this.class_observed+"</b></p></div><div ><h5 style='font-size:12px;text-align:center'><b>"+this.TodayReport+"</b></h5></div>"+Strengthdata
    const table = document.getElementById("container");    
    const options = { background: "white", height: div.clientHeight+50, width: div.clientWidth+50 };
    domtoimage.toPng(div, options).then((dataUrl)=> {  
      var doc = new jsPDF("p","mm","a4");      
      var width = doc.internal.pageSize.getWidth();
      var height = doc.internal.pageSize.getHeight();             
      doc.addImage(dataUrl, 'PNG', 10, 10, width, height);
  
      let pdfOutput = doc.output();      
      let buffer = new ArrayBuffer(pdfOutput.length);
      let array = new Uint8Array(buffer);
      for (var i = 0; i < pdfOutput.length; i++) {
          array[i] = pdfOutput.charCodeAt(i);
      }          
      this.filePath.resolveNativePath('file://')
      .then(filePath => alert('success ' + JSON.stringify(filePath)))
      .catch(err => alert('error ' + JSON.stringify(err)));          
    this.file.listDir(this.file.externalDataDirectory, '').then((folderList) => {
      
    });          
      const directory = this.file.externalDataDirectory;          
      const fileName = "ObservationReport.pdf";
      let options: any = { replace: true };
  
      this.file.checkFile(directory, fileName).then((success)=> {        
        this.file.writeFile(directory,fileName,buffer, options)
        .then((success)=> {
          this.fileOpener.open(directory + fileName, 'application/pdf')
            .then(() => document.getElementById('PrintReport').innerHTML = '')
            .catch(e => alert('error ' + JSON.stringify(e)));          
        })
        .catch((error)=> {          
          alert('error ' + JSON.stringify(error));
        });
      })
      .catch((error)=> {        
        this.file.writeFile(directory,fileName,buffer)
        .then((success)=> {
          this.fileOpener.open(directory + fileName, 'application/pdf')
          .then(() => document.getElementById('PrintReport').innerHTML = ''
          )
            .catch(e => alert('error ' + JSON.stringify(e)));
        })
        .catch((error)=> {          
          alert('error ' + JSON.stringify(error));
        });
      });
    })
    .catch(function (error) {      
      console.error('oops, something went wrong!', error);
    });    
    if (this.platform.is('cordova')) {      
      const fileName = "InspectionReport.pdf";
      let ROOT_DIRECTORY = this.file.externalDataDirectory + fileName
    }         
  }

  getHODInspection() {    
    var date = new Date(this.selectedMonth);
    var month = date.getMonth();
    month = Number(month)+1             
    var year = date.getFullYear();    
    this.selectedMonthData = month;
    
    this.selectedYearData = year;    
    this.selectedMonthAndYear = month+'/'+year
    this.hoddata = [];
    let userdata = {};
    userdata["username"] = this.emis_username;
    userdata["selectedMonth"] = month;
    userdata["selectedYear"] = year;
    this.apiService.getInspectionReport(userdata).subscribe((res:any) => {
      if (res) {        
        this.noData = false;
        if(res?.records.reportData != false){
          this.hoddata = res?.records.reportData;
        }else{
          this.hoddata = []
        }
        this.classTarget = res?.records.targetData;
      } else {
        this.noData = true;
      }
    });
  }
  shareImage = async() =>{          
    this.dateSelected = true;  
    var Months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];    
    var div = await document.getElementById("PrintObservation");      
    this.divdata = div.getElementsByTagName('ion-item')[0].innerHTML;    
    this.innerText = div.getElementsByTagName('ion-item');
     div.getElementsByTagName('ion-item')[0].innerText = "Selected Month : "+ Months[this.selectedMonthData-1]+'-'+this.selectedYearData    
    if(div){       
      const table = document.getElementById("container");    
      let options = {};
      if(div.clientHeight>0){
        options = { background: "white", height: div.clientHeight+100, width: div.clientWidth+100 };
      }else{
        options = { background: "white", height: 792, width: 393 };
      }
      
      domtoimage.toPng(div,options).then((dataUrl)=> {         
        var doc = new jsPDF("p","mm","a4");        
        var width = doc.internal.pageSize.getWidth();
        var height = doc.internal.pageSize.getHeight();             
        doc.addImage(dataUrl, 'PNG', 10, 10, width, height);        
        div.getElementsByTagName('ion-item')[0].innerHTML = this.divdata;        
        let pdfOutput = doc.output();
        let buffer = new ArrayBuffer(pdfOutput.length);
        let array = new Uint8Array(buffer);
        for (var i = 0; i < pdfOutput.length; i++) {
            array[i] = pdfOutput.charCodeAt(i);
        }          
        this.filePath.resolveNativePath('file://')
        .then(filePath => console.log(filePath))
        .catch(err => alert('error ' + JSON.stringify(err)));          
  
        const directory = this.file.externalDataDirectory;          
        const fileName = "InspectionReport.pdf";
        let options: any = { replace: true };
    
        this.file.checkFile(directory, fileName).then((success)=> {          
          this.file.writeFile(directory,fileName,buffer, options)
          .then((success)=> {                      
          })
          .catch((error)=> {
            alert('error ' + JSON.stringify(error));
          });
        })
        .catch((error)=> {          
          this.file.writeFile(directory,fileName,buffer)
          .then((success)=> {
            
          })
          .catch((error)=> {
            alert('error ' + JSON.stringify(error));
          });
        });
      })
      .catch(function (error) {      
      });    
      if (this.platform.is('cordova')) {      
        const fileName = "InspectionReport.pdf";
        let ROOT_DIRECTORY = this.file.externalDataDirectory + fileName
        this.socialSharing.share("Message","Subject", ROOT_DIRECTORY, "")
          .then((entries) => {
            this.dateSelected = false;            
          })
          .catch((error) => {
            this.dateSelected = false;
            alert('error ' + JSON.stringify(error));
          }); 
      } 
      
    }
    this.ngOnInit();
    this.dateSelected = false;
}

  goToBack() {
    this.router.navigate(['/tabs/home']);
  }

}
